"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_mechanical_engineering_de"]=window.LC_CHUNKS["university_mechanical_engineering_de"]||{};window.LC_CHUNKS["university_mechanical_engineering_de"][1]={"university_mechanical_engineering_de:M1-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M1-L1 – Einheiten, Skalierung und Dimensionsanalyse<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> Grundrechenarten und Schulalgebra.<\/p>\n<p><strong>Lernziel:<\/strong> Einheiten fehlerfrei umrechnen und\nGleichungen auf Dimensionshomogenität prüfen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Ein Konstrukteur erhält eine Last in Kilonewton, eine CAD-Fläche in\nQuadratmillimetern und einen Werkstoffkennwert in Megapascal. Werden die\nZahlen ohne Einheiten eingesetzt, entstehen leicht Fehler um mehrere\nZehnerpotenzen. Eine Dimensionsprüfung ist daher Bestandteil der\nRechnung, nicht nachträgliche Kosmetik.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Eine physikalische Größe besteht aus Zahlenwert und Einheit.\nDimensionen beschreiben dagegen die Art einer Größe, unabhängig von der\nEinheit. Für mechanische Probleme genügen häufig Masse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>M<\/mi><annotation encoding=\"application/x-tex\">M<\/annotation><\/semantics><\/math>,\nLänge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nund Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>.\nAus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mi>m<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F=ma<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>F<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>M<\/mi><mi>L<\/mi><msup><mi>T<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">[F]=MLT^{-2}<\/annotation><\/semantics><\/math>;\ndaher ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><msup><mi mathvariant=\"normal\">s<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{N}=1\\,\\mathrm{kg\\,m/s^2}<\/annotation><\/semantics><\/math>.\nAus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>=<\/mo><mi>F<\/mi><mi>/<\/mi><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sigma=F/A<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>σ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>M<\/mi><msup><mi>L<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><msup><mi>T<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">[\\sigma]=ML^{-1}T^{-2}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">P<\/mi><mi mathvariant=\"normal\">a<\/mi><\/mrow><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">N<\/mi><mi mathvariant=\"normal\">/<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{Pa}=1\\,\\mathrm{N/m^2}<\/annotation><\/semantics><\/math>.<\/p>\n<p>Bei Potenzen gilt der Umrechnungsfaktor für die gesamte Einheit:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><mo>=<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>6<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">1\\,\\mathrm{mm^2}=10^{-6}\\,\\mathrm{m^2}<\/annotation><\/semantics><\/math>,\nnicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">10^{-3}\\,\\mathrm{m^2}<\/annotation><\/semantics><\/math>.\nIn einer Summe müssen sämtliche Terme dieselbe Dimension haben. Das\nArgument einer Exponential- oder trigonometrischen Funktion ist\ndimensionslos; ein Winkel in Radiant ist ein Verhältnis zweier Längen.\nPrüfe außerdem die Größenordnung. Wird ein geometrisch ähnlicher Körper\nmit Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>λ<\/mi><annotation encoding=\"application/x-tex\">\\lambda<\/annotation><\/semantics><\/math>\nskaliert, wachsen Flächen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>λ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\lambda^2<\/annotation><\/semantics><\/math>\nund Volumina mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>λ<\/mi><mn>3<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\lambda^3<\/annotation><\/semantics><\/math>.\nBei konstanter Dichte wächst das Gewicht daher schneller als die\ntragende Querschnittsfläche.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_001_DE.svg\"\nalt=\"Umrechnung von Kraft und Fläche mit resultierender Normalspannung.\" />\n<figcaption aria-hidden=\"true\">Umrechnung von Kraft und Fläche mit\nresultierender Normalspannung.<\/figcaption>\n<\/figure>\n<p><em>Umrechnung von Kraft und Fläche mit resultierender\nNormalspannung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Eine idealisierte Zugprobe wird mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">N<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">2\\,\\mathrm{kN}<\/annotation><\/semantics><\/math>\nbelastet. Die Querschnittsfläche beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">100\\,\\mathrm{mm^2}<\/annotation><\/semantics><\/math>.\nUmrechnung:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mn>2000<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F=2000\\,\\mathrm{N}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>100<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>6<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><mo>=<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">A=100\\cdot10^{-6}\\,\\mathrm{m^2}=10^{-4}\\,\\mathrm{m^2}<\/annotation><\/semantics><\/math>.\nDamit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>=<\/mo><mfrac><mn>2000<\/mn><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><\/mfrac><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">P<\/mi><mi mathvariant=\"normal\">a<\/mi><\/mrow><mo>=<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">P<\/mi><mi mathvariant=\"normal\">a<\/mi><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sigma=\\frac{2000}{10^{-4}}\\,\\mathrm{Pa}=20\\,\\mathrm{MPa}.<\/annotation><\/semantics><\/math><\/p>\n<p>Kontrollrechnung im N-mm-System:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2000<\/mn><mi>/<\/mi><mn>100<\/mn><mo>=<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">N<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><mo>=<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">P<\/mi><mi mathvariant=\"normal\">a<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">2000/100=20\\,\\mathrm{N/mm^2}=20\\,\\mathrm{MPa}<\/annotation><\/semantics><\/math>.\nBeide Wege stimmen überein.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wandle 250 mm³ in m³ um.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Ein geometrisch ähnlicher Körper wird in jeder Richtung doppelt so\ngroß. Wie verändern sich Masse und Fläche?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>250<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>9<\/mn><\/mrow><\/msup><mo>=<\/mo><mn>2.5<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>7<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">3<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">250\\cdot10^{-9}=2.5\\cdot10^{-7}\\,\\mathrm{m^3}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bei unveränderter Dichte achtfache Masse, vierfache Fläche.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Dimensionshomogenität ist notwendig, aber kein Beweis für eine\nrichtige Gleichung. Drehmoment und Energie haben beispielsweise dieselbe\nDimension, jedoch unterschiedliche physikalische Bedeutung. Die\nSkalierung setzt geometrische Ähnlichkeit und gleichbleibende Dichte\nvoraus.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Einheiten konsequent mitführen und Potenzen korrekt umrechnen;\nanschließend Richtungen und Kraftkomponenten berücksichtigen.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L2 – Vektoren und\nKräfte<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/university-physics-volume-1/pages/1-4-dimensional-analysis\">OpenStax\n– University Physics Volume 1, 1.4 Dimensional Analysis<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §1.4:\ndimensional consistency · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_mechanical_engineering_de:M1-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M1-L2 – Vektoren und Kräfte<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L1 – Einheiten,\nSkalierung und Dimensionsanalyse<\/a><\/p>\n<p><strong>Lernziel:<\/strong> Kräfte in Komponenten zerlegen,\nResultierende bestimmen und Skalar- sowie Kreuzprodukt anwenden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Ein Seil zieht an einer Maschinenhalterung. Für die Auslegung des\nHalters sind horizontale und vertikale Belastung oft wichtiger als der\nBetrag der Seilkraft allein.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Ein kartesischer Vektor besitzt Komponenten bezüglich orthogonaler\nEinheitsvektoren:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝑭<\/mi><mo>=<\/mo><msub><mi>F<\/mi><mi>x<\/mi><\/msub><msub><mi mathvariant=\"bold-italic\">𝒆<\/mi><mi>x<\/mi><\/msub><mo>+<\/mo><msub><mi>F<\/mi><mi>y<\/mi><\/msub><msub><mi mathvariant=\"bold-italic\">𝒆<\/mi><mi>y<\/mi><\/msub><mo>+<\/mo><msub><mi>F<\/mi><mi>z<\/mi><\/msub><msub><mi mathvariant=\"bold-italic\">𝒆<\/mi><mi>z<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf F=F_x\\mathbf e_x+F_y\\mathbf e_y+F_z\\mathbf e_z<\/annotation><\/semantics><\/math>.\nIn der Ebene, für einen von der positiven x-Achse gemessenen Winkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>θ<\/mi><annotation encoding=\"application/x-tex\">\\theta<\/annotation><\/semantics><\/math>,\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><mi>F<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F_x=F\\cos\\theta<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>y<\/mi><\/msub><mo>=<\/mo><mi>F<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F_y=F\\sin\\theta<\/annotation><\/semantics><\/math>.\nIn dieser Ebene ist der Betrag\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><msqrt><mrow><msubsup><mi>F<\/mi><mi>x<\/mi><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>F<\/mi><mi>y<\/mi><mn>2<\/mn><\/msubsup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">F=\\sqrt{F_x^2+F_y^2}<\/annotation><\/semantics><\/math>;\nKomponenten werden vorzeichenrichtig addiert. Eine Resultierende\nbeschreibt die gemeinsame translatorische Kraftwirkung; bei\nunterschiedlichen Angriffspunkten müssen zusätzlich Momente bilanziert\nwerden.<\/p>\n<p>Das Skalarprodukt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝑭<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝒔<\/mi><mo>=<\/mo><msub><mi>F<\/mi><mi>x<\/mi><\/msub><msub><mi>s<\/mi><mi>x<\/mi><\/msub><mo>+<\/mo><msub><mi>F<\/mi><mi>y<\/mi><\/msub><msub><mi>s<\/mi><mi>y<\/mi><\/msub><mo>+<\/mo><msub><mi>F<\/mi><mi>z<\/mi><\/msub><msub><mi>s<\/mi><mi>z<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf F\\cdot\\mathbf s=F_xs_x+F_ys_y+F_zs_z<\/annotation><\/semantics><\/math>\nliefert bei konstanter Kraft die Arbeit entlang der Verschiebung.\nSenkrechte Vektoren haben ein Skalarprodukt von null. Das Kreuzprodukt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝑴<\/mi><mo>=<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>×<\/mo><mi mathvariant=\"bold-italic\">𝑭<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf M=\\mathbf r\\times\\mathbf F<\/annotation><\/semantics><\/math>\nbeschreibt das Moment um einen Bezugspunkt; seine Richtung folgt der\nRechtsschraubenregel. In der xy-Ebene gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><msub><mi>r<\/mi><mi>x<\/mi><\/msub><msub><mi>F<\/mi><mi>y<\/mi><\/msub><mo>−<\/mo><msub><mi>r<\/mi><mi>y<\/mi><\/msub><msub><mi>F<\/mi><mi>x<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">M_z=r_xF_y-r_yF_x<\/annotation><\/semantics><\/math>.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_002_DE.svg\"\nalt=\"Zerlegung einer Kraft von 500 N in orthogonale Komponenten von 400 N und 300 N.\" />\n<figcaption aria-hidden=\"true\">Zerlegung einer Kraft von 500 N in\northogonale Komponenten von 400 N und 300 N.<\/figcaption>\n<\/figure>\n<p><em>Zerlegung einer Kraft von 500 N in orthogonale Komponenten von\n400 N und 300 N.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Eine Seilkraft besitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><mn>400<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F_x=400\\,\\mathrm N<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>y<\/mi><\/msub><mo>=<\/mo><mn>300<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F_y=300\\,\\mathrm N<\/annotation><\/semantics><\/math>.\nDer Betrag ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><msup><mn>400<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>300<\/mn><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mo>=<\/mo><mn>500<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt{400^2+300^2}=500\\,\\mathrm N<\/annotation><\/semantics><\/math>\nund der Winkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">arctan<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>300<\/mn><mi>/<\/mi><mn>400<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><msup><mn>36.87<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\arctan(300/400)\\approx36.87^\\circ<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.2<\/mn><mo>,<\/mo><mn>0.1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf r=(0.2,0.1)\\,\\mathrm m<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><mn>0.2<\/mn><mo>⋅<\/mo><mn>300<\/mn><mo>−<\/mo><mn>0.1<\/mn><mo>⋅<\/mo><mn>400<\/mn><mo>=<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">N<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">M_z=0.2\\cdot300-0.1\\cdot400=20\\,\\mathrm{N\\,m}<\/annotation><\/semantics><\/math>\n(gegen den Uhrzeigersinn). Verschiebt sich der Angriffspunkt dagegen um\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒔<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.05<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf s=(0.05,0)\\,\\mathrm m<\/annotation><\/semantics><\/math>,\nleistet die Kraft bei gleichbleibender Richtung und Größe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W<\/mi><mo>=<\/mo><mn>400<\/mn><mo>⋅<\/mo><mn>0.05<\/mn><mo>=<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">J<\/mi><\/mrow><annotation encoding=\"application/x-tex\">W=400\\cdot0.05=20\\,\\mathrm J<\/annotation><\/semantics><\/math>.\nDie identischen Zahlenwerte sind Zufall; Moment und Arbeit sind nicht\naustauschbar.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Addiere die Kräfte (100, −20) N und (−30, 80) N.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Arbeit leistet eine Kraft, die stets senkrecht zur momentanen\nBewegungsrichtung steht?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>70<\/mn><mo>,<\/mo><mn>60<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">(70,60)\\,\\mathrm N<\/annotation><\/semantics><\/math>;\nBetrag\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mn>8500<\/mn><\/msqrt><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><mo>≈<\/mo><mn>92.2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt{8500}\\,\\mathrm N\\approx92.2\\,\\mathrm N<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Null, da das lokale Skalarprodukt mit der Verschiebung null\nist.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Die Arkustangensfunktion allein unterscheidet nicht alle Quadranten.\nFür allgemeine Komponenten ist eine zweistellige Winkelfunktion\nsinnvoll. Bei räumlich verteilten Kräften genügt die Resultierende\nallein nicht zur Beschreibung der Drehwirkung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Vektorkomponenten und Momente liefern Gleichungen, deren unbekannte\nGrößen in linearen Systemen bestimmt werden können.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L3 – Lineare\nGleichungssysteme und Matrizen<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/university-physics-volume-1/pages/2-4-products-of-vectors\">OpenStax\n– University Physics Volume 1, 2.4 Products of Vectors<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §2.4:\ncomponents, dot and cross products · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_mechanical_engineering_de:M1-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M1-L3 – Lineare Gleichungssysteme und Matrizen<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L2 – Vektoren und\nKräfte<\/a><\/p>\n<p><strong>Lernziel:<\/strong> Ein lineares Gleichungssystem aus einem\nModell lösen und das Residuum kontrollieren.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Bei mehreren unbekannten Lagerkräften oder Verschiebungen müssen\nGleichungen gleichzeitig erfüllt sein. Ein einzelner Messwert oder eine\neinzelne Bilanz reicht oft nicht aus.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Ein lineares System\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi mathvariant=\"bold-italic\">𝒙<\/mi><mo>=<\/mo><mi mathvariant=\"bold-italic\">𝒃<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A\\mathbf x=\\mathbf b<\/annotation><\/semantics><\/math>\nfasst Koeffizienten in einer Matrix, Unbekannte in einem Vektor und\nbekannte rechte Seiten in einem zweiten Vektor zusammen. Die Zeilen\nentsprechen Gleichungen. Gauß-Elimination kombiniert Gleichungen so,\ndass schrittweise Unbekannte verschwinden. Zulässige Operationen sind\nZeilentausch, Multiplikation einer Zeile mit einem von null\nverschiedenen Faktor und Addition eines Vielfachen einer anderen\nZeile.<\/p>\n<p>Für eine quadratische Matrix mit vollem Rang ist die Lösung\neindeutig. Bei Rangmangel können widersprüchliche Randbedingungen oder\nunendlich viele Lösungen vorliegen. Eine kleine Determinante allein ist\nohne Skalierungsbezug kein zuverlässiger Konditionsindikator. In\nnumerischen Rechnungen werden deshalb Pivotisierung und geeignete\nSkalierung verwendet. Das Residuum\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>=<\/mo><mi mathvariant=\"bold-italic\">𝒃<\/mi><mo>−<\/mo><mi>A<\/mi><mover><mi mathvariant=\"bold-italic\">𝒙<\/mi><mo accent=\"true\">̂<\/mo><\/mover><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf r=\\mathbf b-A\\hat{\\mathbf x}<\/annotation><\/semantics><\/math>\nkontrolliert die Erfüllung der Gleichungen; bei schlecht konditionierter\nMatrix kann es trotzdem einen großen Lösungsfehler geben.<\/p>\n<p>In der linearen Strukturmechanik wird die gleiche Form als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mi mathvariant=\"bold-italic\">𝒖<\/mi><mo>=<\/mo><mi mathvariant=\"bold-italic\">𝒇<\/mi><\/mrow><annotation encoding=\"application/x-tex\">K\\mathbf u=\\mathbf f<\/annotation><\/semantics><\/math>\nverwendet. Die Steifigkeitsmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>K<\/mi><annotation encoding=\"application/x-tex\">K<\/annotation><\/semantics><\/math>\nverknüpft Verschiebungen mit Kräften; fehlende Lagerung kann\nStarrkörpermoden und eine singuläre Matrix erzeugen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_003_DE.svg\"\nalt=\"Zwei lineare Gleichungen und ihr gemeinsamer Schnittpunkt.\" />\n<figcaption aria-hidden=\"true\">Zwei lineare Gleichungen und ihr\ngemeinsamer Schnittpunkt.<\/figcaption>\n<\/figure>\n<p><em>Zwei lineare Gleichungen und ihr gemeinsamer\nSchnittpunkt.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Für zwei normierte unbekannte Größen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x,y<\/annotation><\/semantics><\/math>\ngelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2x+y=10<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mn>2<\/mn><mi>y<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x+2y=8<\/annotation><\/semantics><\/math>.\nMultipliziere die zweite Gleichung mit zwei und subtrahiere die erste:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>y<\/mi><mo>=<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3y=6<\/annotation><\/semantics><\/math>.\nSomit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2<\/annotation><\/semantics><\/math>,\nund aus der ersten Gleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>10<\/mn><mo>−<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=(10-2)/2=4<\/annotation><\/semantics><\/math>.\nPrüfung:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>⋅<\/mo><mn>4<\/mn><mo>+<\/mo><mn>2<\/mn><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\cdot4+2=10<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mo>+<\/mo><mn>2<\/mn><mo>⋅<\/mo><mn>2<\/mn><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">4+2\\cdot2=8<\/annotation><\/semantics><\/math>.\nDas Residuum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,0)<\/annotation><\/semantics><\/math>.\nGeometrisch schneiden sich zwei Geraden genau in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(4,2)<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Löse x+y=7 und x−y=1.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum besitzt x+y=3 und 2x+2y=8 keine Lösung?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Addition ergibt 2x=8, also x=4 und y=3.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die erste Gleichung fordert 2x+2y=6, im Widerspruch zur\nzweiten.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Lineare Systeme gelten nur für lineare oder entsprechend\nlinearisierte Modelle. Reibkontakt, große Deformation und plastisches\nMaterialverhalten können nicht ohne Weiteres durch eine konstante Matrix\nbeschrieben werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Elimination und Residuum sind Grundlagen für numerische Mechanik;\nzeitabhängige Modelle erfordern außerdem Ableitungen und Integrale.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4 – Differential-\nund Integralrechnung<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://ocw.mit.edu/courses/18-06sc-linear-algebra-fall-2011/pages/ax-b-and-the-four-subspaces/elimination-with-matrices/\">MIT\nOCW – Linear Algebra, Elimination with Matrices<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Session Overview:\nelimination method; individual examples are original · Zuletzt\nabgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_mechanical_engineering_de:M1-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M1-L4 – Differential- und Integralrechnung<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L3 – Lineare\nGleichungssysteme und Matrizen<\/a><\/p>\n<p><strong>Lernziel:<\/strong> Ableitungen als Änderungsraten und\nIntegrale als akkumulierte Größen interpretieren.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Eine Vorschubachse beschleunigt beim Anfahren. Der Endwert ihrer\nGeschwindigkeit beschreibt nicht den bis dahin zurückgelegten Weg.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Die Ableitung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>f<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">lim<\/mi><mo>&#8289;<\/mo><\/mrow><mrow><mi>h<\/mi><mo>→<\/mo><mn>0<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>+<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>/<\/mi><mi>h<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f&#39;(t)=\\lim_{h\\to0}[f(t+h)-f(t)]/h<\/annotation><\/semantics><\/math>\nbeschreibt eine lokale Änderungsrate. Für einen Ort\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">x(t)<\/annotation><\/semantics><\/math>\nsind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>=<\/mo><mi mathvariant=\"normal\">d<\/mi><mi>x<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v=\\mathrm dx/\\mathrm dt<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mi mathvariant=\"normal\">d<\/mi><mi>v<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a=\\mathrm dv/\\mathrm dt<\/annotation><\/semantics><\/math>.\nDie SI-Einheiten sind m/s und m/s². Eine stationäre Stelle erfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>f<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f&#39;=0<\/annotation><\/semantics><\/math>;\nob dort ein lokales Extremum vorliegt, kann beispielsweise durch einen\nVorzeichenwechsel der Ableitung oder ein geeignetes Kriterium höherer\nAbleitungen geprüft werden. Auch Randpunkte und nicht differenzierbare\nStellen können Extremstellen sein.<\/p>\n<p>Das bestimmte Integral\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_a^b f(t)\\,\\mathrm dt<\/annotation><\/semantics><\/math>\nsummiert Beiträge über ein Intervall. Der Hauptsatz verbindet es mit\neiner Stammfunktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>F<\/mi><annotation encoding=\"application/x-tex\">F<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><mo>=<\/mo><mi>F<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>F<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\int_a^b f(t)\\,\\mathrm dt=F(b)-F(a)<\/annotation><\/semantics><\/math>,\nwenn die Voraussetzungen erfüllt sind. Für die Mechanik folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>τ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x(t)-x(0)=\\int_0^t v(\\tau)\\,\\mathrm d\\tau<\/annotation><\/semantics><\/math>.\nBei Richtungswechseln ist diese Verschiebung nicht die Weglänge, die\ndurch das Integral von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|v|<\/annotation><\/semantics><\/math>\nentsteht. Für eine ortsabhängige Kraft liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W<\/mi><mo>=<\/mo><mo>∫<\/mo><msub><mi>F<\/mi><mi>x<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">W=\\int F_x\\,\\mathrm dx<\/annotation><\/semantics><\/math>\ndie Arbeit entlang der x-Richtung.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_004_DE.svg\"\nalt=\"Geschwindigkeits-Zeit-Diagramm mit linearer Geschwindigkeit und dreieckiger Wegfläche.\" />\n<figcaption aria-hidden=\"true\">Geschwindigkeits-Zeit-Diagramm mit\nlinearer Geschwindigkeit und dreieckiger Wegfläche.<\/figcaption>\n<\/figure>\n<p><em>Geschwindigkeits-Zeit-Diagramm mit linearer Geschwindigkeit und\ndreieckiger Wegfläche.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Eine hypothetische Achse fährt während\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>t<\/mi><mo>≤<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0\\le t\\le3\\,\\mathrm s<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>a<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v(t)=at<\/annotation><\/semantics><\/math>,\nwobei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><msup><mi mathvariant=\"normal\">s<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">a=2\\,\\mathrm{m/s^2}<\/annotation><\/semantics><\/math>.\nDie Geschwindigkeit nach 3 s ist 6 m/s. Die Beschleunigung ist konstant.\nDer zurückgelegte Weg ergibt sich aus<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>=<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mrow><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msubsup><mi>a<\/mi><mi>t<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><mo>=<\/mo><mfrac><mrow><mi>a<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><mn>2<\/mn><\/mfrac><mo>=<\/mo><mn>9<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta x=\\int_0^{3\\,\\mathrm s}at\\,\\mathrm dt=\\frac{a(3\\,\\mathrm s)^2}{2}=9\\,\\mathrm m.<\/annotation><\/semantics><\/math><\/p>\n<p>Die geometrische Kontrolle über die Dreiecksfläche\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><mo>⋅<\/mo><mn>6<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3\\,\\mathrm s\\cdot6\\,\\mathrm{m/s}/2<\/annotation><\/semantics><\/math>\nergibt ebenfalls 9 m.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Eine konstante Kraft von 80 N wirkt parallel zu einer Verschiebung\nvon 0,25 m. Bestimme die Arbeit.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Ein Körper bewegt sich eine Sekunde mit +2 m/s und eine Sekunde mit\n−2 m/s. Bestimme Verschiebung und Weglänge.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">W = 80 N · 0,25 m = 20 J.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Verschiebung 0 m, Weglänge 4 m.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Die Rechnung mit einer stückweise konstanten Geschwindigkeit\nidealisiert abrupte Übergänge; reale Maschinen haben begrenzte\nBeschleunigung und begrenzten Ruck. Numerische Ableitungen aus\nverrauschten Messdaten können stark schwanken.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Ableitungen und Integrale verknüpfen Zustandsgrößen; Bewegungsgesetze\nführen daraus zu Differentialgleichungen.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L5 –\nDifferentialgleichungen und numerische Fehler<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/calculus-volume-1/pages/3-1-defining-the-derivative\">OpenStax\n– Calculus Volume 1, 3.1 Defining the Derivative<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §3.1: derivative\nas limit · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/calculus-volume-1/pages/5-3-the-fundamental-theorem-of-calculus\">OpenStax\n– Calculus Volume 1, 5.3 The Fundamental Theorem of Calculus<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §5.3:\nderivative and definite integral · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_mechanical_engineering_de:M1-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M1-L5 – Differentialgleichungen und numerische Fehler<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4 – Differential-\nund Integralrechnung<\/a><\/p>\n<p><strong>Lernziel:<\/strong> Eine einfache Anfangswertaufgabe\ndiskretisieren und die Abhängigkeit des Fehlers von der Schrittweite\nbeurteilen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Ein vereinfachtes Modell einer viskos gebremsten Masse sagt voraus,\nwie ihre Geschwindigkeit abnimmt. Die numerische Simulation ersetzt eine\nkontinuierliche Zeitfunktion durch diskrete Zeitpunkte.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Die Bewegungsgleichung einer frei gleitenden Masse mit linearer\nWiderstandskraft lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mover><mi>v<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mo>=<\/mo><mi>−<\/mi><mi>c<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\dot v=-cv<\/annotation><\/semantics><\/math>,\nwobei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>c<\/mi><annotation encoding=\"application/x-tex\">c<\/annotation><\/semantics><\/math>\ndie Einheit kg/s hat. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mi>c<\/mi><mi>/<\/mi><mi>m<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=c/m&gt;0<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>v<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mo>=<\/mo><mi>−<\/mi><mi>k<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\dot v=-kv<\/annotation><\/semantics><\/math>.\nSeparation der Variablen und Anfangsbedingung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>v<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">v(0)=v_0<\/annotation><\/semantics><\/math>\nliefern\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>v<\/mi><mn>0<\/mn><\/msub><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v(t)=v_0\\exp(-kt)<\/annotation><\/semantics><\/math>.<\/p>\n<p>Bei einer allgemeinen Gleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>y<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\dot y=f(t,y)<\/annotation><\/semantics><\/math>\nkann das explizite Euler-Verfahren verwendet werden. Aus der lokalen\nTangentenapproximation folgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mspace width=\"1.0em\"><\/mspace><msub><mi>t<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y_{n+1}=y_n+h f(t_n,y_n),\\quad t_{n+1}=t_n+h.<\/annotation><\/semantics><\/math><\/p>\n<p>Für die gebremste Masse wird daraus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>k<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>v<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">v_{n+1}=(1-kh)v_n<\/annotation><\/semantics><\/math>.\nUnter üblichen Glattheitsannahmen ist der lokale Einschrittfehler\n(ausgehend vom exakten Wert am Schrittanfang) von Ordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>h<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">h^2<\/annotation><\/semantics><\/math>,\nder globale Fehler über ein festes endliches Zeitintervall unter den\nüblichen Stabilitäts- und Lipschitz-Bedingungen von Ordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>.\nFür die lineare Testgleichung mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k&gt;0<\/annotation><\/semantics><\/math>\nklingt der numerische Wert ab, wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo>−<\/mo><mi>k<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|1-kh|&lt;1<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>&lt;<\/mo><mi>k<\/mi><mi>h<\/mi><mo>&lt;<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1&lt;kh&lt;2<\/annotation><\/semantics><\/math>\nentsteht zwar betragsmäßig Abklingen, aber ein hier unphysikalischer\nVorzeichenwechsel.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_005_DE.svg\"\nalt=\"Exakte exponentielle Abnahme und explizite Euler-Näherungen für zwei Zeitschritte.\" />\n<figcaption aria-hidden=\"true\">Exakte exponentielle Abnahme und\nexplizite Euler-Näherungen für zwei Zeitschritte.<\/figcaption>\n<\/figure>\n<p><em>Exakte exponentielle Abnahme und explizite Euler-Näherungen für\nzwei Zeitschritte.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Setze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k=1\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">v_0=1\\,\\mathrm{m/s}<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">h=1\\,\\mathrm s<\/annotation><\/semantics><\/math>\nliefert Euler bereits nach einem Schritt null. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>0.5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">h=0.5\\,\\mathrm s<\/annotation><\/semantics><\/math>\nerhält man nacheinander 0.5, 0.25, 0.125 und 0.0625 m/s. Nach 2 s\nbeträgt der exakte Wert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><mo>≈<\/mo><mn>0.13534<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\exp(-2)\\,\\mathrm{m/s}\\approx0.13534\\,\\mathrm{m/s}<\/annotation><\/semantics><\/math>.\nDer absolute Fehler der feineren Rechnung beträgt rund 0.07284 m/s. Eine\nstabile Rechnung kann also noch eine unzureichende Genauigkeit\nbesitzen.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme für k=1 s⁻¹ und h=0,25 s den ersten Euler-Schritt ab 1\nm/s.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Was geschieht bei k=1 s⁻¹ und h=3 s?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">v₁=(1−0,25)·1=0,75 m/s.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Der Verstärkungsfaktor ist −2; die Folge wechselt das Vorzeichen und\nwächst betragsmäßig.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Der Stabilitätsbereich wurde für genau diese lineare Testgleichung\nhergeleitet. Nichtlineare oder steife Systeme benötigen geeignete\nIntegratoren und eine gesonderte Konvergenzprüfung. Die TUM- und\nKIT-Quellen belegen den curricularen Methodenbereich. Der fachliche\nBeleg zur Stabilität des expliziten Euler-Verfahrens findet sich in\nAbschnitt 2.15.1 der verlinkten NTNU-Lehrunterlagen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Diskretisierung und Modellfehler unterscheiden; auch bei realen\nMessdaten ist Unsicherheit gesondert zu quantifizieren.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6 –\nWahrscheinlichkeit und Statistik<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.ed.tum.de/ed/studium/studienangebot/maschinenwesen-b-sc/\">TUM\n– Maschinenwesen B.Sc.<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Studieninhalte und Studienstruktur;\nGrundlagen 1–4, Wahlbereich 5–6; Mechanik, IT, Werkstoffe, CAD,\nThermofluide, Regelung · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.sle.kit.edu/vorstudium/master-maschinenbau.php\">KIT –\nMaschinenbau M.Sc.<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Studienaufbau; mathematische Methoden, Daten,\nSimulation, Auslegung, zwei Schwerpunkte, Labor, Arbeit; SPO 2025\nverlinkt · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://leifh.folk.ntnu.no/teaching/tkt4140/._main025.html\">NTNU –\nNumerical Methods for Engineers, 2.15 Absolute stability of numerical\nmethods for ODE IVPs<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §2.15.1, Gl. (2.132)–(2.148):\nEuler-Rekursion, Stabilität und Oszillation · Zuletzt abgerufen:\n2026-11-25 · Inhaltlich geprüft: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_mechanical_engineering_de:M1-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M1-L6 – Wahrscheinlichkeit und Statistik<\/h1>\n<p><strong>Kursbereich:<\/strong> M1 – Ingenieurmathematik und Modellierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M1&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L5 –\nDifferentialgleichungen und numerische Fehler<\/a><\/p>\n<p><strong>Lernziel:<\/strong> Mittelwert, Stichprobenstandardabweichung\nund Grenzen statistischer Aussagen über Fertigungsdaten erläutern.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Einstieg<\/h2>\n<p>Fünf gefertigte Wellen haben geringfügig unterschiedliche\nDurchmesser. Ein Mittelwert nahe dem Sollwert sagt noch nicht, wie stark\neinzelne Teile abweichen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grundlagen, Begriffe und Modell<\/h2>\n<p>Eine Stichprobe besteht aus beobachteten Werten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x_1,\\ldots,x_n<\/annotation><\/semantics><\/math>.\nDer arithmetische Mittelwert lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>x<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\bar x=\\sum_i x_i/n<\/annotation><\/semantics><\/math>.\nAls Maß der Streuung dient die Stichprobenvarianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>s<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><mover><mi>x<\/mi><mo accent=\"true\">‾<\/mo><\/mover><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">s^2=\\sum_i(x_i-\\bar x)^2/(n-1)<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>&gt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n&gt;1<\/annotation><\/semantics><\/math>.\nIhre Wurzel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>s<\/mi><annotation encoding=\"application/x-tex\">s<\/annotation><\/semantics><\/math>\nhat dieselbe Einheit wie die Messwerte. Bei unabhängigen, identisch\nverteilten Beobachtungen mit endlicher Varianz ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>s<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">s^2<\/annotation><\/semantics><\/math>\nein erwartungstreuer Schätzer der Populationsvarianz; die\nStandardabweichung selbst ist nicht generell erwartungstreu.<\/p>\n<p>Die Wahrscheinlichkeit eines Ereignisses liegt zwischen null und\neins. Für unabhängige Ereignisse gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mo>∩<\/mo><mi>B<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>B<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P(A\\cap B)=P(A)P(B)<\/annotation><\/semantics><\/math>.\nUnabhängigkeit darf bei aufeinanderfolgenden Fertigungsteilen nicht ohne\nPrüfung angenommen werden: Werkzeugverschleiß kann einen zeitlichen\nTrend erzeugen. Die empirische Häufigkeit ist ein Schätzwert, keine\ngarantierte zukünftige Ausschussquote. Unter unabhängiger\nStichprobenziehung kann die Standardunsicherheit des Mittelwerts aus der\nStreuung als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>/<\/mi><msqrt><mi>n<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">s/\\sqrt n<\/annotation><\/semantics><\/math>\ngeschätzt werden; systematische Kalibrierfehler sind darin nicht\nenthalten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mechanical-engineering-de/media/img/U_MEE_006_DE.svg\"\nalt=\"Fünf hypothetische Durchmessermesswerte um den Mittelwert von 20 mm.\" />\n<figcaption aria-hidden=\"true\">Fünf hypothetische Durchmessermesswerte\num den Mittelwert von 20 mm.<\/figcaption>\n<\/figure>\n<p><em>Fünf hypothetische Durchmessermesswerte um den Mittelwert von 20\nmm.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Durchgerechnetes Beispiel<\/h2>\n<p>Fünf hypothetische Durchmesser sind 19.98, 19.99, 20.00, 20.01 und\n20.02 mm. Der Mittelwert ist exakt 20.00 mm. Die Summe der quadrierten\nAbweichungen ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0.0004<\/mn><mo>+<\/mo><mn>0.0001<\/mn><mo>+<\/mo><mn>0<\/mn><mo>+<\/mo><mn>0.0001<\/mn><mo>+<\/mo><mn>0.0004<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><mo>=<\/mo><mn>0.001<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">(0.0004+0.0001+0+0.0001+0.0004)\\,\\mathrm{mm^2}=0.001\\,\\mathrm{mm^2}<\/annotation><\/semantics><\/math>.\nDamit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><msqrt><mrow><mn>0.001<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><\/msqrt><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mo>≈<\/mo><mn>0.01581<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">s=\\sqrt{0.001/4}\\,\\mathrm{mm}\\approx0.01581\\,\\mathrm{mm}.<\/annotation><\/semantics><\/math><\/p>\n<p>Die geschätzte Standardunsicherheit des Mittelwerts aus der Streuung\nbeträgt bei unabhängigen Beobachtungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.01581<\/mn><mi>/<\/mi><msqrt><mn>5<\/mn><\/msqrt><mo>≈<\/mo><mn>0.00707<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0.01581/\\sqrt5\\approx0.00707\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>.\nOhne festgelegte Spezifikationsgrenzen lässt sich daraus keine\nKonformitätsentscheidung ableiten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Drei Messwerte sind 9, 10 und 11 mm. Berechne Mittelwert und\nStichprobenstandardabweichung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Zwei voneinander unabhängige Teile haben jeweils eine hypothetische\nFehlerwahrscheinlichkeit von 0,02. Wie groß ist die Wahrscheinlichkeit,\ndass beide fehlerhaft sind?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S4\"><summary>Lösungen anzeigen<\/summary>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">10 mm; s=√((1+0+1)/2) mm=1 mm.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">0,02·0,02=0,0004=0,04 %.<\/div><\/li>\n<\/ol>\n<\/details>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Annahmen und Grenzen<\/h2>\n<p>Eine kleine Stichprobe belegt weder Normalverteilung noch\nProzessstabilität. Messunsicherheit, Serienkorrelation und tatsächliche\nSpezifikationen sind getrennt zu prüfen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Übergang<\/h2>\n<p>Statistische Aussagen ergänzen mechanische Modelle. Im nächsten Modul\nwerden Kräfte und Momente an freigeschnittenen Körpern bilanziert.<\/p>\n<p><strong>Weiterlesen:<\/strong> <a\nhref=\"index.html?course=university_mechanical-engineering&amp;module=M2&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M2-L1 –\nFreikörperbilder und Gleichgewicht<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/introductory-statistics-2e/pages/2-5-measures-of-the-center-of-the-data\">OpenStax\n– Introductory Statistics 2e, 2.5 Measures of the Center of the Data<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a>\n· §2.5: sample mean and median · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data\">OpenStax\n– Introductory Statistics 2e, 2.7 Measures of the Spread of the Data<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a>\n· §2.7: standard deviation · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>"};
